import sympy as S
from math import gcd
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('coordinate-lattice',['coordinate choice','determinant area','lattice structure'])
P=S.Point
p=[
q(1,r'How many lattice points lie strictly inside the triangle with vertices (0,0),(8,0),(2,6)?',17,[(24,'Report the area.'),(16,'Report the boundary count.'),(18,'Omit the minus-one correction in Pick’s theorem.'),(25,'Treat every unit square as one interior point.')],[r'The area is 8·6/2=24.',r'The boundary count is gcd(8,0)+gcd(6,6)+gcd(2,6)=8+6+2=16.',r'Pick’s theorem gives I=24-16/2+1=17. Vertices are counted once by the edge gcd sum.'],['Find the area and boundary lattice count separately.','A sloping edge’s lattice contribution is a gcd.'],'Combine determinant area, boundary gcds, and Pick’s theorem.',lambda:sum(y>0 and 3*x>y and x+y<8 for x in range(9) for y in range(7)),'Independent strict half-plane enumeration.'),
q(2,r'Find the area of the pentagon with consecutive vertices (0,0),(6,0),(6,2),(2,5),(0,3).',22,[(44,'Forget the one-half in the determinant sum.'),(30,'Use the bounding rectangle without subtracting corners.'),(20,'Drop one edge contribution.'),(25,'Use the average of unrelated widths and heights.')],[r'Apply the signed cross-product sum in the stated boundary order.',r'The nonzero contributions are 12,26,6, totaling 44.',r'Half the absolute total gives area 22.'],['Use the vertices in boundary order.','Close the final edge back to the first vertex.'],'Compute a nonrectangular polygon area consistently.',lambda:S.Polygon(P(0,0),P(6,0),P(6,2),P(2,5),P(0,3)).area,'Exact polygon area; decomposition into a 6×3 strip with corner adjustments also gives 22.',2),
q(3,r'P is inside rectangle ABCD. If PA²=10, PB²=20, and PC²=34, find PD².',24,[(44,'Add the two opposite squared distances without subtracting PB².'),(14,'Subtract adjacent rather than opposite data.'),(64,'Add all three given squared distances.'),(4,'Use ordinary distances in a squared-distance identity.')],[r'Choose A=(0,0),B=(w,0),C=(w,h),D=(0,h),P=(x,y).',r'Expanding the four squared distances shows PA²+PC²=PB²+PD²; every x and y term cancels.',r'Thus PD²=10+34-20=24.'],['Put the rectangle on coordinate axes.','Pair opposite squared distances before expanding.'],'Discover a distance invariant by coordinate cancellation.',lambda:(lambda x,y,w,h:(x*x+(y-h)**2))(S.Rational(3,4),sqrt:=S.sqrt(S.Rational(151,16)),4,sqrt+S.sqrt(S.Rational(375,16))),'A concrete rectangle realization satisfying the three given distances.'),
q(4,r'What is the distance from the origin to the point equidistant from (0,0),(6,0),(0,8)?',5,[(3,'Report its x-coordinate.'),(4,'Report its y-coordinate.'),(10,'Report the triangle hypotenuse.'),(7,'Add coordinates instead of computing Euclidean distance.')],[r'Equality of distances to (0,0) and (6,0) gives x=3 after squaring and canceling.',r'Equality with (0,8) similarly gives y=4.',r'The distance is √(3²+4²)=5.'],['Use squared-distance equality to obtain linear equations.','The perpendicular bisectors determine the point.'],'Linearize equidistance constraints.',lambda:S.Circle(P(0,0),P(6,0),P(0,8)).center.distance(P(0,0)),'Independent circumcenter calculation.',2),
q(5,r'The point (2,5) is reflected across y=x and then rotated 90° counterclockwise about the origin. What is the sum of its final coordinates?',3,[(7,'Treat both transformations as preserving the coordinate sum.'),(-3,'Reverse the rotation direction.'),(-7,'Negate both original coordinates.'),(0,'Assume the composition sends the point to the origin.')],[r'Reflection across y=x swaps coordinates, giving (5,2).',r'A counterclockwise quarter-turn sends (x,y) to (-y,x), yielding (-2,5).',r'The sum is 3. The order matters.'],['Write the coordinate rule for each transformation.','Apply the second rule to the result of the first.'],'Compose transformations in the specified order.',lambda:sum(S.Matrix([[0,-1],[1,0]])*S.Matrix([[0,1],[1,0]])*S.Matrix([2,5])),'Independent matrix composition.',2),
q(6,r'A 90° counterclockwise rotation about (0,0) is followed by a 90° counterclockwise rotation about (2,0). Their composition is a half-turn. Find the distance from its center to the origin.',S.sqrt(2),[(1,'Ignore one coordinate of the center.'),(2,'Use the distance between the two rotation centers.'),(S.sqrt(5),'Use the wrong sign in the translation.'),(0,'Assume the center remains the origin.')],[r'The first map sends (x,y) to (-y,x). Translate around (2,0), rotate again, and translate back to get (2-x,-2-y).',r'A half-turn about (a,b) has map (2a-x,2b-y), so its center is (1,-1).',r'The distance to the origin is √2.'],['Express the rotation about a nonorigin center as translate, rotate, translate back.','Compare the final map with a general half-turn.'],'Identify a composed transformation through its affine map.',lambda:P(1,-1).distance(P(0,0)),'The fixed point (1,-1) is verified by both successive rotations.'),
q(7,r'A square has opposite vertices (1,2) and (7,10). Find its area.',50,[(100,'Use diagonal squared as area.'),(25,'Halve diagonal squared twice.'),(48,'Treat coordinate differences as adjacent square sides.'),(70,'Use an unsquared length with a diagonal component.')],[r'The diagonal squared is 6²+8²=100.',r'A square diagonal has squared length twice the side squared.',r'The area, equal to side squared, is 100/2=50.'],['Use the diagonal before trying to locate the other vertices.','The square diagonal determines area directly.'],'Choose a diagonal invariant that avoids unnecessary coordinates.',lambda:abs(S.Polygon(P(1,2),P(8,3),P(7,10),P(0,9)).area),'Independent construction of the other two vertices.',2),
q(8,r'How many lattice points lie strictly between (0,0) and (18,30) on their connecting segment?',5,[(6,'Include one endpoint in the gcd count.'),(7,'Include both endpoints.'),(17,'Count every integer x-coordinate.'),(29,'Count every integer y-coordinate.')],[r'The primitive direction vector is (3,5), obtained by dividing by gcd(18,30)=6.',r'The lattice points on the segment are k(3,5) for k=0 through 6.',r'Only k=1 through 5 are strictly interior, so there are five.'],['Reduce the direction vector to coprime components.','Distinguish intervals, endpoints, and strictly interior points.'],'Use primitive lattice directions.',lambda:sum(30*x==18*y for x in range(1,18) for y in range(1,30)),'Direct collinearity enumeration.',2),
q(9,r'How many distinct rays from the origin pass through at least one point (a,b) with integers $1\le a,b\le5$?',19,[(25,'Count repeated collinear points as different rays.'),(15,'Identify slopes with their reciprocals.'),(20,'Double-count the diagonal ray.'),(10,'Count only points with b≤a.')],[r'Each ray has a unique primitive positive integer direction (a,b) with gcd(a,b)=1.',r'Within the 5×5 array, the counts of coprime b values for a=1,2,3,4,5 are 5,3,4,3,4.',r'The sum is 19; every nonprimitive point reduces to one of these directions.'],['Points on one ray have the same reduced coordinate ratio.','Count primitive pairs instead of all points.'],'Quotient a grid count by collinearity through gcd reduction.',lambda:len({F(b,a) for a in range(1,6) for b in range(1,6)}),'Independent set of reduced slopes.'),
q(10,r'A rectangle has vertices (0,0),(x,0),(x,y),(0,y), with x,y positive and $x/4+y/6=1$. What is its maximum area?',6,[(12,'Use half the intercept triangle’s doubled area.'),(24,'Use the bounding rectangle.'),(5,'Add the half-intercepts.'),(3,'Halve the rectangle area as if it were a triangle.')],[r'Solve for y=6-3x/2, with 0<x<4.',r'Then xy=6x-3x²/2=6-(3/2)(x-2)².',r'The maximum is 6, attained at x=2,y=3.'],['Write area as a function of one coordinate.','Complete a square and check the maximizing point is allowed.'],'Translate a geometric maximum into an attainable quadratic bound.',lambda:(lambda t: t*(6-S.Rational(3,2)*t))(2),'Independent equal-factor AM–GM on x/4 and y/6 gives xy≤6.'),
q(11,r'Find the square of the distance from the origin to the line through (2,3) and (5,9).',F(1,5),[(F(1,25),'Square the denominator twice.'),(1,'Use the y-intercept as the perpendicular distance.'),(5,'Invert the distance ratio.'),(F(4,5),'Use the x-coefficient as the constant term.')],[r'The line is y=2x-1, or 2x-y-1=0.',r'The perpendicular from the origin has slope -1/2 and meets the line at (2/5,-1/5).',r'The squared distance is 4/25+1/25=1/5.'],['Find the line equation and a perpendicular through the origin.','Use their intersection as the nearest point.'],'Derive a point-to-line distance through a perpendicular intersection.',lambda:S.Line(P(2,3),P(5,9)).distance(P(0,0))**2,'Independent exact point-to-line distance.',2),
q(12,r'How many lattice points lie on the circle $x^2+y^2=25$?',12,[(8,'Miss the axis points.'),(4,'Count only the axis points.'),(16,'Give axis points four independent sign choices.'),(20,'Count all bounded coordinates without checking the equation.')],[r'Nonnegative solutions are (0,5),(3,4),(4,3),(5,0).',r'The two axis patterns give four points total; the two nonzero patterns give four sign choices each.',r'The total is 4+8=12.'],['Bound each coordinate by five and inspect square complements.','Sign counts differ when a coordinate is zero.'],'Count symmetry orbits with different stabilizers.',lambda:sum(x*x+y*y==25 for x in range(-5,6) for y in range(-5,6)),'Exhaustive exact lattice enumeration.',2),
q(13,r'The midpoints of the sides of the quadrilateral with consecutive vertices (0,0),(8,0),(6,6),(0,4) form a new quadrilateral. Find its area.',18,[(36,'Use the original area.'),(9,'Apply a quarter-area rule for a triangle to a quadrilateral.'),(24,'Use the bounding rectangle’s half-area.'),(12,'Ignore one of the original diagonal triangles.')],[r'The original area by the cross-product sum is (8·6+6·4)/2=36.',r'The midpoint quadrilateral is a parallelogram with half the original area; this follows by removing four corner triangles or comparing to both diagonals.',r'The requested area is 18.'],['Compute the original area first.','Relate the midpoint figure to the original diagonals.'],'Combine polygon area with the midpoint parallelogram theorem.',lambda:S.Polygon(P(4,0),P(7,3),P(3,5),P(0,2)).area,'Direct area of the four midpoint coordinates.'),
q(14,r'How many lattice points P in $0\le x\le6$, $0\le y\le4$ make triangle (0,0),(6,4),P have area 6?',4,[(2,'Keep only one sign of the determinant.'),(6,'Count all points on one boundary line without the box restriction.'),(8,'Double-count points after using absolute value.'),(0,'Assume a sloping fixed base cannot give integer area.')],[r'The determinant formula gives area |6y-4x|/2.',r'Thus |3y-2x|=6. In the given box, the two linear equations yield (3,0),(0,2),(6,2),(3,4).',r'There are four points. The absolute value accounts for both sides of the fixed base.'],['Translate the fixed-area condition into a determinant equation.','Solve both signs and enforce the coordinate bounds.'],'Intersect area loci with a bounded lattice.',lambda:sum(abs(6*y-4*x)==12 for x in range(7) for y in range(5)),'Exhaustive determinant enumeration.')]
e=[
q(101,r'Find the area of the triangle with vertices (1,1),(7,3),(2,6).',14,[(28,'Forget to halve the determinant.'),(15,'Use coordinate differences as perpendicular legs.'),(12,'Drop one signed cross term.'),(7,'Halve twice.')],[r'Translate the first vertex to the origin. The two edge vectors become (6,2) and (1,5).',r'The determinant 6·5-2·1=28 is the signed area of their parallelogram.',r'The triangle occupies half that area, so its area is 14.',r'Translation preserves area and simplifies the computation. An independent bounding-box decomposition removes the three surrounding right triangles from a 6×5 rectangle.'],['Translate one vertex to the origin.','Use a determinant rather than treating oblique edges as perpendicular.'],'Choose coordinates that simplify an area calculation.',lambda:S.Polygon(P(1,1),P(7,3),P(2,6)).area,'Independent polygon determinant calculation.',2),
q(102,r'How many lattice points lie on the boundary of the triangle (0,0),(6,0),(2,4)?',12,[(15,'Count each vertex on two edges.'),(9,'Exclude all vertices.'),(14,'Assume every integer x gives a point on each sloping side.'),(10,'Miss one primitive step on the diagonal edge.')],[r'The horizontal edge has six primitive intervals. The sloping edges have gcd(4,4)=4 and gcd(2,4)=2 primitive intervals.',r'For a closed polygon, summing interval counts gives boundary points because each vertex is the end of one interval and the beginning of another.',r'The boundary count is 6+4+2=12.',r'Alternatively, count 7+5+3 points on the three closed edges and subtract the three vertices counted twice. The same twelve points result.'],['Find the primitive step on each edge.','Correct for shared vertices if counting closed-edge points.'],'Explain the boundary gcd count without double-counting vertices.',lambda:len({(x,y) for x in range(7) for y in range(5) if (y==0) or (x+y==6 and 2<=x<=6) or (y==2*x and x<=2)}),'Independent union of lattice points on the three segments.',2)]
finish('coordinate-lattice','Coordinates, transformations & lattice geometry','Geometry','coordinates ratio-geometry integer-constraints',38,'574–597',
 [r'Coordinates are a representation choice, not a command to expand every distance. Put a useful side on an axis, exploit a diagonal or midpoint, and look for cancellations before solving for all unknowns. A well-chosen coordinate system can turn an angle-free geometry problem into linear algebra with two variables.',r'Lattice problems add an integer structure to the picture. Primitive directions, determinants, and boundary gcds connect geometry with number theory; the continuous area and the discrete point count must be kept distinct.'],
 [section('Choose a coordinate system that removes work',r'Translations and rotations preserve distances and areas, so place a convenient vertex at the origin and a side on an axis. A rectangle then has only two unknown dimensions. Squared-distance differences often cancel the quadratic terms, leaving linear equations for an unknown point or a relation independent of the point.',r'An equidistance condition describes a perpendicular bisector. Expanding squared distances is useful because the same x²+y² occurs on both sides. For several conditions, solve the resulting linear system before taking any square roots.',r'A diagonal can determine a square’s area without locating the other vertices. A midpoint construction can determine a quadrilateral’s area fraction without determining every side. Coordinate work is most effective when it preserves such geometric structure rather than replacing it with an unnecessarily large system.'),
 section('Determinants measure signed area',r'With one triangle vertex at the origin and edge vectors (a,b),(c,d), the signed parallelogram area is ad-bc; the triangle area is half its absolute value. The sign records orientation. A fixed positive area therefore usually produces two parallel linear loci, one on each side of a fixed base.',r'For a polygon, sum consecutive cross products in boundary order and close the final edge. Reordering vertices arbitrarily can create a crossed figure and change the signed sum. Use the absolute value only after the signed contributions have been combined.',r'An area maximum can become a one-variable quadratic after a line constraint eliminates a coordinate. Completing the square provides a bound and an equality point. Check that this point lies in the permitted region; an unconstrained algebraic maximum does not automatically solve a constrained geometry problem.'),
 section('Track integer and transformation structure',r'A segment with integer displacement (u,v) has gcd(|u|,|v|) primitive intervals. It has one more lattice point if both endpoints are included and one fewer if both are excluded. On a closed polygon, summing the interval counts counts each boundary lattice point once.',r'Pick’s theorem states K=I+B/2-1 for a simple lattice polygon. Compute the geometric area and the boundary count separately, then solve for the interior count. For a small example, verify by direct strict inequalities; this helps expose boundary points accidentally included as interior.',r'For transformations, write each coordinate rule and apply them in the specified order. A rotation about a nonorigin center requires translating to that center and back. Two transformations with familiar individual effects can compose to a different center or orientation. A fixed-point calculation provides a useful independent check of the final map.')],
 ['Choose coordinates that simplify geometry before calculating.','Use signed determinants and lattice gcds with correct boundary conventions.','Compose transformations and enforce geometric constraints on algebraic solutions.'],
 [r'Translate one triangle vertex to the origin and derive area from a parallelogram determinant.',r'Reduce an integer direction by its gcd to count primitive intervals.',r'Translate to a rotation center, apply the origin rotation, and translate back.'],
 'A coordinate difference is not necessarily a perpendicular height. Use a determinant or establish perpendicularity before multiplying lengths for area.',e,p,
 dict(prompt=r'For the triangle (0,0),(10,0),(4,6), compute its boundary lattice count and then its interior lattice count.',answer=r'$B=18$ and $I=22$.',steps=[r'The edge contributions are gcd(10,0)=10, gcd(6,6)=6, and gcd(4,6)=2.',r'The area is 30, so I=30-18/2+1=22.']),
 ['squared-distance cancellation','determinant area','primitive lattice directions','affine transformations'],
 [(r'K=\tfrac12|ad-bc|','Triangle determinant','finding area from two edge vectors without perpendicular heights','The vectors share the same initial vertex.'),(r'B=\sum_{\text{edges}}\gcd(|\Delta x|,|\Delta y|)','Lattice boundary count','counting boundary lattice points without double-counting vertices','The polygon is closed and every vertex has integer coordinates.'),(r'K=I+\frac B2-1','Pick’s theorem','connecting polygon area with interior and boundary lattice points','The polygon is simple with lattice vertices.'),(r'(x,y)\mapsto(-y,x)','Counterclockwise quarter-turn','rotating a point ninety degrees about the origin','For another center, translate to the center first and translate back afterward.')], 'coordinates')
